package com.aoo.bcg.poker;
import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class TrickTakingEngineTest{@Test void enforcesFollowCategoryAndAwardsTrick(){TrickTakingRules rules=new TrickTakingRules(){public int category(int card){return card/100;}public int winner(Map<Integer,Integer> trick,int leader){return trick.entrySet().stream().max(Map.Entry.comparingByValue()).orElseThrow().getKey();}public int points(Map<Integer,Integer> trick){return 1;}};var state=new TrickTakingState(Map.of(0,List.of(103),1,List.of(104,205)),0,0,Map.of(),Map.of(),false);var engine=new TrickTakingEngine();state=engine.play(state,0,103,rules);var led=state;assertThrows(IllegalStateException.class,()->engine.play(led,1,205,rules));state=engine.play(state,1,104,rules);assertEquals(1,state.scores().get(1));assertTrue(state.trick().isEmpty());}}
